import { createSakeResearch } from "./sakeResearchPhase1.js";
import { applyPhase21Audit } from "./sakeResearchPhase21.js";

const verifiedAt = "2026-10-03";

// Each fact belongs to this product, not the brewery or its entire brand.
function product(item) {
  const sourceType = item.sourceType || "breweryOfficial";
  const evidence = (item.facts || []).map(([feature, meaning]) => {
    const sourceUrl = item.featureSourceOverrides?.[feature] || item.url;
    const featureSourceType = item.additionalSources?.find((source) => source.url === sourceUrl)?.type || sourceType;
    return { feature, sourceUrl, sourceType: featureSourceType, verifiedAt, meaning, tag: feature, url: sourceUrl, basis: meaning };
  });
  const specs = { ...(item.specs || {}) };
  if (specs.riceVariety) {
    const genericLabels = specs.riceVariety.filter((name) => /未取得|未記載|国産米|一般米|その他/.test(name));
    specs.riceVariety = specs.riceVariety.filter((name) => !genericLabels.includes(name));
    if (genericLabels.length) specs.riceMaterialLabel = genericLabels.join("・");
  }
  const fieldEvidence = [...(item.fieldEvidence || [])];
  const traceField = (field, value) => {
    if (value == null || value === "" || (Array.isArray(value) && !value.length)) return;
    const override = fieldEvidence.find((entry) => entry.field === field) || fieldEvidence.find((entry) => field.startsWith(`${entry.field}.`));
    if (override?.field === field) return;
    fieldEvidence.push({
      field, value,
      sourceUrl: override?.sourceUrl || item.url,
      sourceType: override?.sourceType || sourceType,
      verifiedAt,
      meaning: override?.meaning || "対象商品の記載を採用。ブランド全体や別商品の情報は転用しない。",
    });
  };
  for (const [field, value] of Object.entries(specs)) traceField(`specs.${field}`, value);
  for (const [field, value] of Object.entries(item.classification || {})) traceField(`classification.${field}`, value);
  for (const field of ["servingTemperatures", "recommendedTemperatureRange", "officialPairings", "season", "seasonalLimited", "limitedDistribution", "breweryLimited", "beginnerFriendly"]) {
    traceField(field, item[field]);
  }
  return createSakeResearch({
    ...item,
    researchPhase: "2",
    lastVerifiedAt: verifiedAt,
    identity: {
      productName: item.productName,
      brewery: item.brewery,
      prefecture: item.prefecture,
      brandName: item.brandName,
      officialProductUrl: sourceType === "breweryOfficial" && !item.needsIdentification ? item.url : null,
    },
    verifiedFeatureTags: evidence.map((entry) => entry.feature),
    editorialTags: item.editorialTags || [],
    featureTags: [...evidence.map((entry) => entry.feature), ...(item.editorialTags || [])],
    featureEvidence: evidence,
    specs,
    sources: item.url ? [{ type: sourceType, name: item.sourceName || `${item.brewery} ${item.productName}`, url: item.url, verifiedAt, scope: item.needsIdentification ? "identificationOnly" : "product" }, ...(item.additionalSources || [])] : [],
    fieldEvidence,
    pairingEvidence: (item.officialPairings || []).map((dish) => ({ dish, ...fieldEvidence.find((entry) => entry.field === "officialPairings") })),
    identificationNote: item.identificationNote || null,
    dataConfidence: item.dataConfidence || "high",
  });
}

